const ex = (id, title, prompt, starter, solution, cases, hints, sample = '') => ({
  id,
  title,
  prompt,
  examples: [{ input: sample || 'Run your code', output: typeof cases[0].expected === 'string' ? cases[0].expected.replaceAll('\\n', '\n') : cases[0].expected }],
  starter,
  solution,
  hints,
  failureMessage: 'You are close. Try a small input and compare each step with the example.',
  tests: cases.map((test, index) => ({
    ...test,
    type: test.type || 'output',
    description: test.description || `Example ${index + 1}`,
    inputs: test.inputs || [],
    expected: typeof test.expected === 'string' ? test.expected.replaceAll('\\n', '\n') : test.expected,
  })),
});

const lesson = (id, title, objectives, explanation, example, exercises, tryCode = example) => ({
  id, title, objectives, explanation, example, tryCode, exercises,
});

const pair = (key, first, second) => [
  ex(`${key}-1`, first[0], first[1], first[2], first[3], first[4], first[5], first[6]),
  ex(`${key}-2`, second[0], second[1], second[2], second[3], second[4], second[5], second[6]),
];

