export const lessons = course.flatMap((level) => level.modules.map((item) => ({ ...item, levelId: level.id })));
export const exercises = lessons.flatMap((item) => item.exercises.map((exercise) => ({ ...exercise, lessonId: item.id, levelId: item.levelId })));
export const lessonById = Object.fromEntries(lessons.map((item) => [item.id, item]));
export const exerciseById = Object.fromEntries(exercises.map((item) => [item.id, item]));
